<?php

namespace Tests\Feature\Docs;

use Tests\TestCase;

/**
 * The deployed Engine (GitLab
 * `GITHUB/develop`, at `daf4ad737`, later at `53c9a6ff4` – the deploy
 * history) is the contract for everything outside
 * WordPress. Every non-WordPress Engine path the panel calls
 * must be served by that commit's `core/routes/api.php`.
 *
 * The route list is the committed fixture
 * `tests/Feature/Docs/engine-develop-routes.txt`, generated by the documented
 * command:
 *
 *   ENGINE_BRANCH=origin/GITHUB/develop scripts/generate-engine-develop-routes.sh
 *
 * The panel paths are read from the one place Engine paths live:
 * `packages/engine-client/src/Api/*.php` and
 * `EngineClient.php`.
 *
 * The list is generated from the 2.2.0 contract, `origin/develop-2-2-0` (`459c7a38f`, develop + feat/wordpress +
 * the Engine gap fixes; re-generated at `19ae8a136` with the later Engine work, which adds the
 * WordPress import's test, plugin-package and cancel routes), so the WordPress management endpoints (`wp/*`, `wordpress/*`) are
 * checked too (until then they were out of scope). The panel requires Engine 2.3.0 since
 * 2026-11-07: the paths only a 2.3.0 serves are checked against `engine-2-3-0-routes.txt` below.
 *
 *   ENGINE_BRANCH=origin/develop-2-2-0 scripts/generate-engine-develop-routes.sh
 */
final class EngineDevelopRouteTest extends TestCase
{
    /**
     * Global Engine paths the panel calls only on an Engine that lists the
     * `project_source` feature (`EngineFeatures`, Engine 2.3.0): they are checked against the 2.3.0 list
     * (`engine-2-3-0-routes.txt`, generated with
     * `ENGINE_BRANCH=origin/develop-2-3-0 OUT=tests/Feature/Docs/engine-2-3-0-routes.txt`).
     * `PUT projects/{username}/source` shares its path with the 2.2.0 `POST`.
     */
    private const PROJECT_SOURCE_PATHS = ['uploads', 'uploads/', 'vault/deploy-keys'];

    public function test_every_engine_path_the_panel_calls_exists_on_the_required_engine(): void
    {
        $routes = $this->routes();
        $next = $this->routes('engine-2-3-0-routes.txt');
        $calls = $this->engineCalls();

        // A scan that finds nothing would pass vacuously; the panel calls far
        // more than this.
        $this->assertGreaterThan(50, count($calls), 'The Engine-path scan found suspiciously few paths.');

        $offenders = [];

        foreach ($calls as $call) {
            [$path, $scope] = $call;
            $gated = $scope === 'global' && in_array($path, self::PROJECT_SOURCE_PATHS, true);
            if (! self::exists($gated ? $next : $routes, $path, $scope)) {
                $offenders[] = ($scope === 'project' ? 'projects/{username}/' : '').$path;
            }
        }

        $offenders = array_values(array_unique($offenders));
        sort($offenders);

        $this->assertSame(
            [],
            $offenders,
            "These Engine paths are not served by develop's core/routes/api.php:\n".implode("\n", $offenders),
        );
    }

    /**
     * The matcher really detects a missing path and clears a present one, so the
     * guard cannot pass by matching everything (or nothing).
     */
    public function test_the_matcher_detects_a_missing_and_a_present_project_path(): void
    {
        $routes = ['/projects/{username}/files/exists', '/projects/all', '/tasks/{id}'];

        $this->assertTrue(self::exists($routes, 'files/exists', 'project'));
        $this->assertTrue(self::exists($routes, '', 'project'));
        $this->assertTrue(self::exists($routes, 'projects/all', 'global'));
        $this->assertTrue(self::exists($routes, 'tasks/', 'global'));
        $this->assertFalse(self::exists($routes, 'files/nope', 'project'));
        $this->assertFalse(self::exists($routes, 'system/info', 'global'));
    }

    /**
     * @return list<string>
     */
    private function routes(string $file = 'engine-develop-routes.txt'): array
    {
        $path = base_path('tests/Feature/Docs/'.$file);
        $this->assertFileExists($path, 'The committed develop route list is missing; run scripts/generate-engine-develop-routes.sh.');

        return array_values(array_filter(array_map('trim', file($path) ?: []), static fn (string $line): bool => $line !== ''));
    }

    /**
     * Every Engine path the panel builds, with its scope: a project-relative
     * `enginePath('...')` path or a global `server/<path>` one.
     *
     * @return list<array{0: string, 1: string}>
     */
    private function engineCalls(): array
    {
        $root = (string) realpath(base_path('../packages/engine-client/src'));
        $files = array_merge(glob($root.'/Api/*.php') ?: [], [$root.'/EngineClient.php']);

        $calls = [];
        foreach ($files as $file) {
            $source = (string) file_get_contents($file);

            // Project-relative: $app->enginePath('files/exists'); no argument is
            // the project resource itself.
            preg_match_all('~enginePath\(\s*[\'"]([^\'"]*)[\'"]~', $source, $match);
            foreach ($match[1] as $path) {
                $calls[] = [$path, 'project'];
            }
            if (preg_match('~enginePath\(\s*\)~', $source) === 1) {
                $calls[] = ['', 'project'];
            }

            // Global: $this->engine->get('system/info'). `stream` is excluded –
            // its first argument is the HTTP method, not a path (the path is an
            // `enginePath(...)`, captured above).
            preg_match_all('~engine->(?:get|post|put|delete|download|upload)\(\s*[\'"]([^\'"]*)[\'"]~', $source, $match);
            foreach ($match[1] as $path) {
                $calls[] = [$path, 'global'];
            }

            // Global: the EngineClient's own $this->get('projects/all') and
            // $this->stream('GET', "tasks/{$taskId}/logs/stream") calls.
            preg_match_all('~\$this->(?:get|post|put|delete|download|upload)\(\s*[\'"]([^\'"]*)[\'"]~', $source, $match);
            foreach ($match[1] as $path) {
                $calls[] = [$path, 'global'];
            }
            preg_match_all('~\$this->stream\(\s*[\'"][A-Z]+[\'"]\s*,\s*[\'"]([^\'"]*)[\'"]~', $source, $match);
            foreach ($match[1] as $path) {
                $calls[] = [$path, 'global'];
            }
        }

        return $calls;
    }

    /**
     * The list is generated from `develop-2-2-0`: it carries the WordPress
     * endpoints and the core download the panel calls, which develop
     * `f72fec570` does not serve.
     */
    public function test_the_committed_route_list_carries_the_2_2_0_additions(): void
    {
        $routes = $this->routes();

        foreach (['/projects/{username}/wp/core', '/projects/{username}/wp/core/download', '/projects/{username}/wp/core/install', '/wordpress/migrations', '/wordpress/migrations/test', '/wordpress/migrations/plugin-package', '/wordpress/migrations/plugin-package/download', '/wordpress/migrations/{id}/cancel'] as $path) {
            $this->assertContains($path, $routes, "engine-develop-routes.txt is missing {$path}; regenerate it from origin/develop-2-2-0.");
        }
    }

    /**
     * The committed list is generated from the pinned
     * deploy ref `29ae50bc0`, which added exactly these 13 paths over the former
     * `6c83024`. A missing entry means the fixture was not regenerated after the
     * contract move (nothing was removed, so the route matcher alone would not
     * notice).
     */
    public function test_the_committed_route_list_carries_the_29ae_additions(): void
    {
        $routes = $this->routes();

        // The 13 paths 29ae50bc0 adds to core/routes/api.php (research map §4.1).
        $added = [
            '/mcp-tokens/{id}/projects',
            '/projects/{username}/backup-schedule',
            '/projects/{username}/backups/{id}/items/{item}/download',
            '/projects/{username}/env-vars',
            '/projects/{username}/files/list',
            '/projects/{username}/files/thumbnail',
            '/projects/{username}/mysql/databases/{dbname}/rename',
            '/projects/{username}/push/diff',
            '/projects/{username}/sftp-accounts/kill-sessions',
            '/projects/{username}/sftp-accounts/{sftpUser}/kill-sessions',
            '/projects/{username}/source',
            '/source/refs',
            '/tasks',
        ];

        foreach ($added as $path) {
            $this->assertContains($path, $routes, "engine-develop-routes.txt is missing {$path}; regenerate it from the pinned ref.");
        }
    }

    /**
     * The list is regenerated from `53c9a6ff4` (the deploy
     * history the panel reads), which adds exactly these two paths over
     * `daf4ad737` and removes none.
     */
    public function test_the_committed_route_list_carries_the_deploy_history(): void
    {
        $routes = $this->routes();

        foreach (['/projects/{username}/deploys', '/projects/{username}/deploys/{deploy}/log'] as $path) {
            $this->assertContains($path, $routes, "engine-develop-routes.txt is missing {$path}; regenerate it from 53c9a6ff4.");
        }
    }


    /**
     * @param  list<string>  $routes
     */
    private static function exists(array $routes, string $path, string $scope): bool
    {
        $segments = $path === '' ? [] : explode('/', trim($path, '/'));
        if ($scope === 'project') {
            $segments = array_values(array_merge(
                ['projects', '{username}'],
                array_filter($segments, static fn (string $segment): bool => $segment !== ''),
            ));
        }

        foreach ($routes as $route) {
            if (self::startsWith($route, $segments)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Whether $route's literal/placeholder segments begin with every $needle
     * segment. A route placeholder (`{name}`) matches any needle segment, and
     * an interpolated needle segment (`{$id}`) only matches a placeholder.
     *
     * @param  list<string>  $needle
     */
    private static function startsWith(string $route, array $needle): bool
    {
        $segments = explode('/', trim($route, '/'));
        if (count($segments) < count($needle)) {
            return false;
        }

        foreach ($needle as $index => $segment) {
            if ($segment === '') {
                return false;
            }
            $routeSegment = $segments[$index];
            if ($routeSegment !== $segment && ! self::isPlaceholder($routeSegment)) {
                return false;
            }
        }

        return true;
    }

    private static function isPlaceholder(string $segment): bool
    {
        return preg_match('~^\{.*\}$~', $segment) === 1;
    }
}
